#!/usr/bin/env python3
"""
Phase 14: Savant Self-Optimization
Monitors response quality and dynamically tunes model temperature and context size.
"""
import orjson as json, random
from pathlib import Path
import numpy as np

ROOT=Path.home()/ "savant"/"logs"
CONF=ROOT/"ai_tuning.json"

### — Savant Insight —
# Purpose: record — auto-annotated by Savant DocSynth
# Added 2025-10-30 19:24:14
def record(feedback:int):
    data={"score":feedback,"session":random.random()}
    hist=[]
    if CONF.exists(): hist=json.loads(CONF.read_text())
    hist.append(data)
    CONF.write_text(json.dumps(hist[-50:],indent=2))

### — Savant Insight —
# Purpose: tune — auto-annotated by Savant DocSynth
# Added 2025-10-30 19:24:14
def tune():
    if not CONF.exists(): return {"temperature":0.7,"context":0.8}
    data=json.loads(CONF.read_text())
    mean=np.mean([d["score"] for d in data])
    temp=max(0.2,min(1.2,0.7+(0.5-mean)*0.3))
    ctx=max(0.5,min(1.0,0.8+(mean-0.5)*0.2))
    return {"temperature":round(temp,2),"context":round(ctx,2)}